def tokenize(self, text):
        text = text.lower()

        tokens = re.findall(
            r"[A-Za-z_][A-Za-z0-9_]*",
            text
        )

        expanded_tokens = []

        for token in tokens:
            expanded_tokens.append(token)

            if "_" in token:
                expanded_tokens.extend(token.split("_"))

        return expanded_tokens

def search(self, query, top_k=5):
        tokenized_query = self.tokenize(query)

        scores = self.bm25.get_scores(tokenized_query)

        ranked_indices = scores.argsort()[::-1][:top_k]

        results = []

        for index in ranked_indices:
            results.append({
                "index": int(index),
                "score": float(scores[index]),
                "document": self.documents[index]
            })

        return results

def __init__(self, model=None):
        self.model = model or SentenceTransformer(
            "sentence-transformers/all-MiniLM-L6-v2"
        )

        self.documents = None
        self.document_embeddings = None

def encode(self, texts):
        return self.model.encode(
            texts,
            normalize_embeddings=True,
            convert_to_numpy=True
        )

def search(self, query, documents=None, top_k=5):

        if documents is not None and self.document_embeddings is None:
            self.index(documents)

        if self.document_embeddings is None:
            raise ValueError("Call index(documents) before search().")

        query_embedding = self.encode([query])[0]

        scores = np.dot(
            self.document_embeddings,
            query_embedding
        )

        ranked_indices = np.argsort(scores)[::-1][:top_k]

        results = []

        for index in ranked_indices:
            results.append({
                "index": int(index),
                "score": float(scores[index]),
                "document": self.documents[index]
            })

        return results

def fuse(self, result_lists, top_k=10):
        scores = {}
        documents = {}

        for results in result_lists:
            for rank, result in enumerate(results, start=1):

                document_index = result["index"]

                rrf_score = 1 / (self.k + rank)

                scores[document_index] = (
                    scores.get(document_index, 0) + rrf_score
                )

                documents[document_index] = result["document"]

        ranked_indices = sorted(
            scores,
            key=scores.get,
            reverse=True
        )[:top_k]

        fused_results = []

        for index in ranked_indices:
            fused_results.append({
                "index": index,
